function mixin(sourceObj, targetObj) {
  for (var key in sourceObj) {
    if (!(key in targetObj)) {
      targetObj[key] = sourceObj[key];
    }
  }
  return targetObj;
}
var Vehicle = {
  engines: 1,
  ignition: function () {
    console.log('引擎啟動中');
  },
};
var Car = mixin(Vehicle, {
  wheels: 4,
});
Car.ignition();
console.log(Car.engines, Car.wheels);
Vehicle.engines = 2; // 混入之後才修改來源物件
console.log(Car.engines);

