var Vehicle = {
  engines: 1,
  ignition: function () {
    console.log('Turning on my engine.');
  },
  drive: function () {
    this.ignition();
    console.log('Steering and moving forward!');
  },
};
var Car = {
  wheels: 4,
  ignition: function () {
    Vehicle.ignition.call(this);
  },
  drive: function () {
    Vehicle.drive.call(this);
    console.log('Rolling on all ' + this.wheels + ' wheels!');
  },
};
Car.drive();

